```java
package io.github.diodeme.ji.remote;

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.OptionalInt;

/**
 * The identity OpenSSH matches a target's host key against: the host and port a connection to the target
 * actually reaches, and therefore the name its key must be pinned under.
 *
 * <p>A {@code host} may be a {@code ~/.ssh/config} alias, and OpenSSH resolves that alias before it looks a
 * host key up — the key it validates is the resolved {@code HostName}'s, on the port the configuration
 * selected. Asking the local {@code ssh} client itself ({@code ssh -G}, config evaluation only: no
 * connection, no credential, no key material) keeps the pinned name and the validated name the same string,
 * which is what a {@code StrictHostKeyChecking=yes} connection requires.
 *
 * <p>When the local client cannot describe the target — it is absent, or the user's configuration is
 * unreadable — the host is used exactly as the user gave it: a target that cannot be resolved is never
 * silently replaced by a guess.
 */
public record SshHostKeyTarget(String host, OptionalInt port) {
    /** The local client whose view of the target every other SSH command on this machine shares. */
    static final String CLIENT = "ssh";
    private static final int DEFAULT_PORT = 22;
    /** Bounds config evaluation; the operation timeout is the outer bound. */
    private static final Duration RESOLUTION_TIMEOUT = Duration.ofSeconds(10);

    public SshHostKeyTarget {
        port = port == null ? OptionalInt.empty() : port;
        if (host == null || host.isBlank() || host.startsWith("-")
                || host.chars().anyMatch(Character::isWhitespace)
                || host.indexOf(',') >= 0 || host.indexOf('|') >= 0) {
            throw new IllegalArgumentException("invalid host key target");
        }
        if (port.isPresent() && (port.getAsInt() < 1 || port.getAsInt() > 65_535)) {
            throw new IllegalArgumentException("invalid host key target port");
        }
    }

    /** The target as the user named it, for the case where no local client can describe it. */
    public static SshHostKeyTarget of(SshTarget target) {
        return new SshHostKeyTarget(target.host(), target.port());
    }

    /** A host with the port left to the connection. */
    public static SshHostKeyTarget ofHost(String host) {
        return new SshHostKeyTarget(host, OptionalInt.empty());
    }

    /**
     * The target as OpenSSH resolves it, or as the user gave it when the local client cannot describe it.
     */
    static SshHostKeyTarget resolve(ProcessRunner processes, SshTarget target) {
        ProcessRunner.Result result = processes.run(command(target), RESOLUTION_TIMEOUT);
        if (result.exitCode() != 0) return of(target);
        String host = null;
        OptionalInt port = OptionalInt.empty();
        for (String line : result.stdout().split("\\R")) {
            int separator = line.indexOf(' ');
            if (separator <= 0) continue;
            String value = line.substring(separator + 1).strip();
            switch (line.substring(0, separator)) {
                case "hostname" -> host = value;
                case "port" -> port = port(value);
                default -> { }
            }
        }
        if (host == null || host.isBlank()) return of(target);
        try {
            return new SshHostKeyTarget(host, port);
        } catch (IllegalArgumentException unusable) {
            return of(target);
        }
    }

    /**
     * The config-evaluation argv: the same client, port and user the connection itself will use, so the
     * values OpenSSH reports are the values it will connect with. An omitted port or user stays omitted here
     * too — the user's own configuration decides it.
     */
    static List<String> command(SshTarget target) {
        var command = new ArrayList<String>();
        command.add(CLIENT);
        target.port().ifPresent(port -> command.addAll(List.of("-p", Integer.toString(port))));
        target.user().ifPresent(user -> command.addAll(List.of("-l", user)));
        command.add("-G");
        command.add(target.host());
        return List.copyOf(command);
    }

    /** How OpenSSH spells this endpoint in a known hosts file: {@code host}, or {@code [host]:port}. */
    public String canonical() {
        int port = port().orElse(DEFAULT_PORT);
        return port == DEFAULT_PORT ? host : "[" + host + "]:" + port;
    }

    /** Whether a known hosts host field names this endpoint. */
    public boolean matchesKnownHostsField(String field) {
        if (field == null || field.isBlank() || field.startsWith("|") || field.contains(",")) return false;
        if (field.startsWith("[")) {
            int end = field.indexOf(']');
            if (end < 0) return false;
            String written = field.startsWith("]:", end) ? field.substring(end + 2) : "";
            return field.substring(1, end).equals(host) && written.equals(portAsText());
        }
        return field.equals(host) && port().orElse(DEFAULT_PORT) == DEFAULT_PORT;
    }

    private String portAsText() { return Integer.toString(port().orElse(DEFAULT_PORT)); }

    private static OptionalInt port(String value) {
        try {
            int port = Integer.parseInt(value);
            return port >= 1 && port <= 65_535 ? OptionalInt.of(port) : OptionalInt.empty();
        } catch (NumberFormatException notANumber) {
            return OptionalInt.empty();
        }
    }
}
```

